// Revenue conversion hook: records paid events on successful checkout
// Called by checkout completion endpoint

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = path.join(__dirname, '..', 'data', 'revenue_events.log');

function recordPaidEvent(amount, currency, userId, orderId) {
  const event = {
    type: 'paid',
    amount: amount || 0,
    currency: currency || 'USD',
    userId: userId || 'anonymous',
    orderId: orderId || 'unknown',
    timestamp: new Date().toISOString()
  };
  try {
    fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n', 'utf8');
    return true;
  } catch (err) {
    console.error('Revenue hook write error:', err);
    return false;
  }
}

module.exports = { recordPaidEvent };
